#if UNITY_EDITOR
using System.Collections;using System.Collections.Generic;using System.IO;using System;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
namespace OneMoreTime.Tests {
public class LevelTests {
 RunManager game; readonly List<InputFrame> movie=new List<InputFrame>();bool exported;
 [Serializable]class Movie{public float fixedStep=.02f;public InputFrame[] frames;}

 IEnumerator Load(string name="L01_Freeze"){EditorSceneManager.LoadSceneInPlayMode("Assets/_OneMoreTime/Scenes/"+name+".unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;game=UnityEngine.Object.FindAnyObjectByType<RunManager>();game.AutoTick=false;game.InputSource=new TestPlayerInput();game.ResetRun();if(game.Relic!=null){game.player.ResetAt(game.Relic.Anchor-Vector2.up*.5f);game.Tick(default);while(game.State==FlowState.AbilityDialogue)game.AdvanceAbilityDialogue();game.FinishAbilityDemo();game.ResetRun();}movie.Clear();exported=false;Step(default,2);}
 void Step(InputFrame f,int count=1){for(int i=0;i<count;i++){movie.Add(f);game.Tick(f);if(game.State==FlowState.Completed&&!exported){exported=true;File.WriteAllText("Artifacts/Logs/solution-L0"+game.config.level+".json",JsonUtility.ToJson(new Movie{frames=movie.ToArray()}));}f.jump=f.freeze=f.trace=f.retry=false;Physics2D.SyncTransforms();}}
 void Walk(float x){for(int i=0;i<300&&game.State==FlowState.Playing&&Mathf.Abs(game.player.Position.x-x)>.06f;i++)Step(new InputFrame{move=Mathf.Sign(x-game.player.Position.x)});Step(default,6);}
 void JumpTo(float x,int ticks=65){Step(new InputFrame{jump=true,held=true,move=Mathf.Sign(x-game.player.Position.x)});for(int i=1;i<ticks;i++)Step(new InputFrame{held=true,move=Mathf.Abs(game.player.Position.x-x)>.08f?Mathf.Sign(x-game.player.Position.x):0});Step(default,6);}
 void ApproachPlate(){Walk(6.3f);JumpTo(10.3f);Walk(12.8f);}
 void RecordRelay(){Walk(11.4f);Step(new InputFrame{trace=true});Step(default,100);JumpTo(16.3f);Walk(21.7f);Step(default,90);Step(new InputFrame{jump=true,held=true});Step(new InputFrame{held=true},55);Step(default,25);Step(new InputFrame{trace=true});}
 void RecordTiming(bool waits=true,bool returnToA=true){Walk(4);Step(default,40);Walk(6);Step(new InputFrame{trace=true});Step(default,waits?85:1);Walk(16);Step(default,waits?90:1);if(returnToA){Walk(6);Step(default,waits?110:1);}Step(new InputFrame{trace=true});}
 void UpperTiming(){JumpTo(7);Walk(9);Step(new InputFrame{trace=true});Walk(12.3f);JumpTo(15.4f,38);JumpTo(19.2f,38);JumpTo(22.3f,38);Walk(24);for(int i=0;i<200&&game.echo.Pose.position.x<15;i++)Step(default);Walk(26.3f);JumpTo(29.2f,38);JumpTo(33.2f,38);Walk(37.5f);}
 [UnityTest]public IEnumerator PreparationResetAndDeathDiscard(){yield return Load("L03_Trace");Step(new InputFrame{move=1},30);game.SetPaused(true);float before=game.Clock;int count=game.Recorder.Count;Step(default,100);Assert.AreEqual(before,game.Clock);Assert.AreEqual(count,game.Recorder.Count);game.SetPaused(false);Step(new InputFrame{retry=true,trace=true,freeze=true});Assert.IsNull(game.Memory);Assert.AreEqual(0,game.Recorder.Count);Assert.AreEqual(0,game.Clock);Step(new InputFrame{trace=true});Step(default,30);game.player.ResetAt(new Vector2(2,-6));Step(default);Assert.AreEqual(FlowState.DeathReview,game.State);Step(new InputFrame{retry=true});Assert.IsNull(game.Memory);Assert.AreEqual(FlowState.Playing,game.State);Assert.AreEqual(0,game.Recorder.Count);Assert.Less(Vector2.Distance(game.player.Position,game.config.spawn),.001f);}
 [UnityTest]public IEnumerator ManualTraceStartSavePlayAndClear(){yield return Load("L03_Trace");Step(new InputFrame{move=1},50);Assert.IsFalse(game.IsRecording);Assert.AreEqual(0,game.Recorder.Count);Vector2 start=game.player.Position;Step(new InputFrame{trace=true});Assert.IsTrue(game.IsRecording);Assert.That(Vector2.Distance(game.Recorder.At(0).position,start),Is.LessThan(.15f));Step(new InputFrame{trace=true});Assert.IsNull(game.Memory);Assert.IsTrue(game.IsRecording);Step(default,100);Step(new InputFrame{trace=true});var saved=game.Memory;Assert.NotNull(saved);Assert.IsFalse(game.IsRecording);Assert.IsFalse(game.echo.Active);Step(new InputFrame{trace=true});Assert.AreEqual(PlaybackState.Playing,game.Playback);Step(default,5);Step(new InputFrame{retry=true});Assert.AreSame(saved,game.Memory);Assert.AreEqual(PlaybackState.Ready,game.Playback);Step(new InputFrame{trace=true});Step(new InputFrame{trace=true});Assert.IsNull(game.Memory);Assert.IsFalse(game.IsRecording);Assert.AreEqual(0,game.Recorder.Count);Assert.IsFalse(game.echo.Active);Assert.That(Vector2.Distance(game.player.Position,game.config.spawn),Is.LessThan(.001f));Step(default,100);Assert.AreEqual(0,game.Recorder.Count);}
 [UnityTest]public IEnumerator IdleDeathAndRecordingFreezeReset(){yield return Load("L03_Trace");game.player.ResetAt(new Vector2(2,-6));Step(default);Assert.AreEqual(FlowState.Playing,game.State);Assert.IsFalse(game.IsRecording);Step(new InputFrame{trace=true});Step(default,30);Step(new InputFrame{freeze=true});Assert.AreEqual(MemoryKind.Freeze,game.Memory.Kind);Assert.IsFalse(game.IsRecording);Step(new InputFrame{trace=true});Assert.AreEqual(MemoryKind.Freeze,game.Memory.Kind);Step(new InputFrame{freeze=true});Assert.IsNull(game.Memory);Assert.IsFalse(game.IsRecording);}
 [UnityTest]public IEnumerator TimingNoMemoryAndCrumblePauseSafePoint(){yield return Load("L04_Timing");Step(new InputFrame{jump=true,held=true,move=1});Step(new InputFrame{held=true,move=1},65);Step(new InputFrame{move=1},300);Assert.AreNotEqual(FlowState.Completed,game.State);Assert.Less(game.player.Position.x,16);var c=UnityEngine.Object.FindObjectsByType<CrumblingPlatform>()[0];game.player.ResetAt(new Vector2(c.solid.bounds.center.x,c.solid.bounds.max.y+.01f));Step(default,3);Assert.Greater(c.Remaining,0);float remaining=c.Remaining;game.SetPaused(true);Step(default,100);Assert.AreEqual(remaining,c.Remaining);game.SetPaused(false);for(int i=0;i<40&&!c.Collapsed;i++)Step(default);Assert.IsTrue(c.Collapsed);game.player.ResetAt(new Vector2(22.5f,5));Step(default,200);Assert.Greater(game.player.Position.x,22);Assert.That(game.player.Position.y,Is.EqualTo(5).Within(.02f));Assert.AreEqual(FlowState.Playing,game.State);}
 [UnityTest]public IEnumerator FreezeNormalSolution(){yield return Load();Walk(6.8f);Step(new InputFrame{jump=true,held=true,move=1});Step(new InputFrame{held=true,move=1},5);Step(new InputFrame{freeze=true,held=true,move=1});var saved=game.Memory;Assert.NotNull(saved);Walk(6.8f);JumpTo(saved.Sample(0).position.x);Assert.IsTrue(game.player.OnEcho,"board "+game.player.Position+" echo "+saved.Sample(0).position);JumpTo(11.8f);Assert.Greater(game.player.Position.y,4.2f,"cliff "+game.player.Position);Walk(17.3f);JumpTo(21.6f);Walk(26.5f);Assert.AreEqual(FlowState.Completed,game.State);for(int i=0;i<10;i++){game.ResetRun();Assert.AreSame(saved,game.Memory);}game.Rerecord();Assert.IsNull(game.Memory);}
 [UnityTest]public IEnumerator TraceNormalSolution(){yield return Load("L03_Trace");RecordRelay();Assert.NotNull(game.Memory,"recording lost "+game.player.Position);Assert.AreEqual(MemoryKind.Trace,game.Memory.Kind);var snapshot=game.Memory;Walk(11.4f);Step(new InputFrame{trace=true});JumpTo(11.4f);Assert.IsTrue(game.player.OnEcho,"board");bool crossed=false;for(int i=0;i<400&&(game.echo.Pose.position.x<21||game.echo.Pose.position.y<2.8f);i++){Step(default);if(game.player.Position.x>16&&game.player.OnEcho)crossed=true;}Assert.IsTrue(crossed,"must ride across gap");Assert.Greater(game.player.Position.x,21,"relay launch "+game.player.Position);Step(new InputFrame{jump=true,held=true});Step(new InputFrame{held=true},13);Step(new InputFrame{held=true,move=1},55);Assert.Greater(game.player.Position.y,6.2f,"upper "+game.player.Position);Walk(32.5f);Assert.AreEqual(FlowState.Completed,game.State);game.ResetRun();Assert.AreSame(snapshot,game.Memory);Step(new InputFrame{trace=true});Step(default,600);Assert.AreEqual(PlaybackState.Finished,game.Playback);Assert.IsFalse(game.echo.Active);Step(new InputFrame{trace=true});Assert.IsNull(game.Memory);}
 [UnityTest]public IEnumerator PressureNormalSolutionAndReset(){yield return Load("L02_Pressure");ApproachPlate();Assert.That(game.player.Position.y,Is.EqualTo(1.4f).Within(.02f));Step(new InputFrame{freeze=true});var plate=UnityEngine.Object.FindAnyObjectByType<PressurePlate>();var door=UnityEngine.Object.FindAnyObjectByType<LinkedDoor>();Assert.IsTrue(plate.Pressed);Assert.IsTrue(door.Open);ApproachPlate();JumpTo(12.8f);Assert.IsTrue(game.player.OnEcho);JumpTo(15.2f);Walk(18.3f);JumpTo(22.6f);Walk(25.3f);JumpTo(29.6f);Walk(32.5f);Assert.AreEqual(FlowState.Completed,game.State,"end "+game.player.Position);game.ResetRun();Assert.IsTrue(door.Open);game.Rerecord();Assert.IsFalse(door.Open);Assert.IsFalse(plate.Pressed);}
 [UnityTest]public IEnumerator PressureSoloAndAirborneFreezeFail(){yield return Load("L02_Pressure");ApproachPlate();var door=UnityEngine.Object.FindAnyObjectByType<LinkedDoor>();Assert.IsTrue(door.Open);Step(new InputFrame{jump=true,held=true,move=1});Step(new InputFrame{held=true,move=1},5);Assert.IsFalse(door.Open);Step(new InputFrame{held=true,move=1},70);Assert.AreNotEqual(FlowState.Completed,game.State);Assert.Less(game.player.Position.x,14);game.Rerecord();ApproachPlate();Step(new InputFrame{jump=true,held=true});Step(new InputFrame{held=true},5);Step(new InputFrame{freeze=true,held=true});Assert.IsFalse(door.Open);}
 [UnityTest]public IEnumerator TimingNormalSolution(){yield return Load("L04_Timing");RecordTiming();Assert.NotNull(game.Memory);Assert.Less(game.Memory.Duration,10);UpperTiming();Assert.AreEqual(FlowState.Completed,game.State,"Timing endpoint "+game.player.Position+" echo "+game.echo.Pose.position+" time "+game.PlaybackTime);var saved=game.Memory;game.ResetRun();Assert.AreSame(saved,game.Memory);foreach(var c in UnityEngine.Object.FindObjectsByType<CrumblingPlatform>()){Assert.IsFalse(c.Collapsed);Assert.AreEqual(-1,c.Remaining);}}
 [UnityTest]public IEnumerator TimingFreezeCannotOpenBothDoors(){foreach(float target in new[]{6f,16f}){yield return Load("L04_Timing");Walk(4);Step(default,40);Walk(target);Step(new InputFrame{freeze=true});UpperTiming();Assert.AreNotEqual(FlowState.Completed,game.State);}}
 [UnityTest]public IEnumerator TimingMustReturnToFirstPlate(){yield return Load("L04_Timing");RecordTiming(true,false);UpperTiming();Assert.AreNotEqual(FlowState.Completed,game.State,"A-B without return must not complete");var last=game.transform.Find("Door C").GetComponent<LinkedDoor>();Assert.IsFalse(last.Open);}
 [UnityTest]public IEnumerator FreezeOnGroundDoesNotBridgeCliff(){yield return Load();Walk(6.8f);Step(new InputFrame{freeze=true});Walk(6.8f);JumpTo(6.8f);Assert.IsTrue(game.player.OnEcho);JumpTo(12);Assert.AreNotEqual(FlowState.Completed,game.State);}
 [UnityTest]public IEnumerator TooHighFreezeDoesNotAutoCorrect(){yield return Load();Walk(6.8f);Step(new InputFrame{jump=true,held=true});Step(new InputFrame{held=true},20);Step(new InputFrame{freeze=true,held=true});var pose=game.Memory.Sample(0);Assert.Greater(pose.position.y+game.player.tuning.backHeight,3.5f);Walk(6.8f);JumpTo(6.8f);Assert.IsFalse(game.player.OnEcho);Assert.That(game.echo.Pose.position,Is.EqualTo(pose.position));Assert.AreNotEqual(FlowState.Completed,game.State);}
 [UnityTest]public IEnumerator LongPreparationAndFiftyRetries(){yield return Load("L03_Trace");Step(new InputFrame{trace=true});Step(default,3000);Assert.AreEqual(501,game.Recorder.Count);Step(new InputFrame{trace=true});var snapshot=game.Memory;int count=UnityEngine.Object.FindObjectsByType<Transform>().Length;long bytes=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong();var watch=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<50;i++){Step(new InputFrame{trace=true});Step(default,5);Step(new InputFrame{retry=true});Assert.AreSame(snapshot,game.Memory);Assert.AreEqual(PlaybackState.Ready,game.Playback);Assert.AreEqual(count,UnityEngine.Object.FindObjectsByType<Transform>().Length);}watch.Stop();File.WriteAllText("Artifacts/Logs/retry-performance.txt",$"50 retries: {watch.Elapsed.TotalMilliseconds:F3} ms total; objects={count}; memoryBefore={bytes}; memoryAfter={UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong()}; ringCapacity={Recorder.Capacity}");}
 [UnityTest]public IEnumerator DeathReviewKeepsOnlyLivingFrames(){yield return Load("L03_Trace");Step(new InputFrame{trace=true});Step(default,30);int count=game.Recorder.Count;game.player.ResetAt(new Vector2(2,-6));Step(new InputFrame{freeze=true,trace=true,retry=true});Assert.AreEqual(FlowState.DeathReview,game.State);Assert.AreEqual(count,game.Recorder.Count);Step(default,100);Assert.AreEqual(count,game.Recorder.Count);Step(new InputFrame{trace=true});Assert.AreEqual(RunPhase.Execution,game.Phase);Assert.Greater(game.Memory.Frame(game.Memory.Count-1).position.y,-1);game.ResetRun();Step(new InputFrame{trace=true});Step(default,10);float t=game.PlaybackTime;game.SetPaused(true);Step(default,100);Assert.AreEqual(t,game.PlaybackTime);game.SetPaused(false);Step(default);Assert.Greater(game.PlaybackTime,t);}
 [UnityTest]public IEnumerator TraceLevelFreezeSweepCannotReachExit(){yield return Load("L03_Trace");for(int freezeTick=2;freezeTick<=24;freezeTick+=2){game.Rerecord();Walk(11.4f);JumpTo(16.3f);Walk(21.7f);Step(new InputFrame{jump=true,held=true});Step(new InputFrame{held=true},freezeTick);Step(new InputFrame{freeze=true,held=true});Walk(11.4f);JumpTo(16.3f);Walk(21.7f);JumpTo(21.7f);JumpTo(25);Assert.AreNotEqual(FlowState.Completed,game.State,"Freeze ascent tick "+freezeTick);Assert.Less(game.player.Position.x,23);}}
 [UnityTest]public IEnumerator TimingWithoutWaitingFailsAtRequiredDoors(){yield return Load("L04_Timing");RecordTiming(false);UpperTiming();Assert.AreNotEqual(FlowState.Completed,game.State);}
 [UnityTest]public IEnumerator LowerRouteCannotRideThroughSeparation(){yield return Load("L04_Timing");Step(new InputFrame{trace=true});Walk(4);Step(default,40);Walk(18);Step(default,100);Step(new InputFrame{jump=true,held=true});Step(new InputFrame{held=true},55);Step(new InputFrame{trace=true});Walk(4);Step(default,40);Walk(18);Step(new InputFrame{trace=true});for(int i=0;i<400&&game.echo.Pose.position.x<17.8f;i++)Step(default);Step(new InputFrame{jump=true,held=true});for(int i=0;i<200;i++){Step(new InputFrame{held=true});Assert.LessOrEqual(game.player.Position.y,2.52f,"The solid lower ceiling must block both jumping and carry");}Assert.AreNotEqual(FlowState.Completed,game.State);}
 [UnityTest]public IEnumerator NoMemoryCannotClimb(){yield return Load();foreach(float x in new[]{5f,6f,6.8f,7.1f}){game.ResetRun();Walk(x);JumpTo(12);Step(new InputFrame{move=1},100);Assert.AreNotEqual(FlowState.Completed,game.State);}}
 [UnityTest]public IEnumerator FreezeSecondPressClearsAndPauseStopsClock(){yield return Load();Step(new InputFrame{freeze=true});var saved=game.Memory;game.player.ResetAt(new Vector2(11,3));Step(new InputFrame{freeze=true});Assert.IsNull(game.Memory);Assert.That(Vector2.Distance(game.player.Position,game.config.spawn),Is.LessThan(.001f));Step(new InputFrame{freeze=true});saved=game.Memory;float clock=game.Clock;game.SetPaused(true);Step(new InputFrame{move=1},50);Assert.AreEqual(clock,game.Clock);game.SetPaused(false);for(int i=0;i<10;i++){game.player.ResetAt(new Vector2(3,-6));Step(new InputFrame{freeze=true,retry=true});Assert.AreSame(saved,game.Memory);Assert.AreEqual(RunPhase.Execution,game.Phase);} }
}
}
#endif
